 <div class="stat">
 <span>Status</span>
 <strong>Active</strong>
 </div>
 <div class="stat">
 <span>Next Wake</span>
 <strong id="next-wake">--:-- UTC</strong>
 </div>
 <div class="stat">
 <span>Cycle Progress</span>
 <strong id="cycle-progress">--</strong>
 </div>
 <div class="stat">
 <span>Last Wake</span>
 <strong id="last-wake">--:-- UTC</strong>
 </div>
